package org.jlinalg.cli;

import static org.junit.jupiter.api.Assertions.*;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

class FumaExpressionCliTest {
    @TempDir Path temp;
    private ArrayList<String> args(String output)throws Exception {
        Files.writeString(temp.resolve("symbols.tsv"),"ensg\tsymbol\nE1\tA\nE2\tB\nE3\tC\nE4\tD\n");Files.writeString(temp.resolve("query.txt"),"E1\nE2\n");Files.writeString(temp.resolve("background.txt"),"E1\nE2\nE3\nE4\n");
        Files.writeString(temp.resolve("log2.tsv"),"ensg\tLiver\tBrain\nE3\t0.0\t3.5\nE2\t10.25\t0.0\nE1\t-1.5\t1.0\nE4\t0.0\t0.0\n");Files.writeString(temp.resolve("norm.tsv"),"ensg\tLiver\tBrain\nE3\t-0.5\t0.5\nE2\t1.0\t-1.0\nE1\t-2.0\t2.0\nE4\t0.0\t0.0\n");Files.writeString(temp.resolve("deg.txt"),"all\t4\tE1:E2:E3:E4\nLiver.up\t99\tE1:E2\nBrain.up\t0\t\nBrain.down\t2\tE3:E4\nLiver.twoside\t2\tE1:E2\n");
        var a=new ArrayList<>(List.of("--method","expression","--build","test-build","--annotation-id","test-annotation","--expression-id","test-expression","--deg-id","test-deg","--duplicates","error","--outside-query","error"));
        for(String key:List.of("symbols","query","background","log2","norm","deg-sets"))a.addAll(List.of("--"+key,temp.resolve(switch(key){case "symbols"->"symbols.tsv";case "log2","norm"->key+".tsv";case "deg-sets"->"deg.txt";default->key+".txt";}).toString()));a.addAll(List.of("--out",temp.resolve(output).toString()));return a;
    }
    private int run(List<String> args){return FumaToolsCli.run(args.toArray(String[]::new),new PrintStream(new ByteArrayOutputStream()),new PrintStream(new ByteArrayOutputStream()));}
    private String read(String output,String name)throws Exception{return Files.readString(temp.resolve(output).resolve(name));}
    @Test void successPreservesMatricesFamiliesAuditIdentitiesAndWarnings()throws Exception {assertEquals(0,run(args("ok")));String matrix=read("ok","log2-expression.tsv");assertTrue(matrix.indexOf("E2\tB")<matrix.indexOf("E1\tA"));assertTrue(matrix.contains("-1.5\t1.0"));assertTrue(read("ok","DEG.txt").contains("DEG.up\tLiver\t2\t2\t0.166666666666666"));assertTrue(read("ok","deg-tests.tsv").contains("99\t2\t2"));assertTrue(read("ok","WARNINGS.md").contains("Required action"));assertTrue(read("ok","manifest.yaml").contains("input_sha256"));assertTrue(read("ok","session.json").contains("test-expression"));}
    @Test void originalGatesAreVisibleAndNotInterpretedAsNoEnrichment()throws Exception {var a=args("gated");Files.writeString(temp.resolve("query.txt"),"E1\nUnknown\n");assertEquals(0,run(a));assertFalse(Files.exists(temp.resolve("gated/DEG.txt")));assertFalse(Files.exists(temp.resolve("gated/log2-expression.tsv")));assertTrue(read("gated","WARNINGS.md").contains("DEG OUTPUT SKIPPED"));assertTrue(read("gated","WARNINGS.md").contains("EXPRESSION OUTPUT SKIPPED"));assertTrue(read("gated","session.json").contains("\"deg_source_gate_opened\":false"));}
    @Test void explicitSourceQuerySizeCreatesProminentDiagnostic()throws Exception {var a=args("outside");Files.writeString(temp.resolve("query.txt"),"E1\nE2\nUnknown\n");assertEquals(2,run(a));a.set(a.indexOf("--outside-query")+1,"source-size");a.set(a.size()-1,temp.resolve("retained").toString());assertEquals(0,run(a));assertTrue(read("retained","WARNINGS.md").contains("SOURCE POPULATION DIAGNOSTIC"));assertTrue(read("retained","query-outside-background.tsv").contains("Unknown"));}
    @Test void duplicatePoliciesAreEnforcedAndAudited()throws Exception {var a=args("dup");Files.writeString(temp.resolve("query.txt"),"E1\nE1\nE2\n");assertEquals(2,run(a));a.set(a.indexOf("--duplicates")+1,"original-count");a.set(a.size()-1,temp.resolve("counted").toString());assertEquals(0,run(a));assertTrue(read("counted","session.json").contains("\"duplicate_query_entries\":1"));assertTrue(read("counted","WARNINGS.md").contains("SOURCE POPULATION DIAGNOSTIC"));}
    @Test void malformedAndNonfiniteResourcesFailWithRetainedDiagnostics()throws Exception {var a=args("bad");Files.writeString(temp.resolve("norm.tsv"),"ensg\tA\tB\nE1\tNaN\t1\n");assertEquals(2,run(a));assertTrue(read("bad","WARNINGS.md").startsWith("# ANALYSIS FAILED"));assertTrue(read("bad","analysis-status.json").contains("failed"));assertFalse(Files.exists(temp.resolve("bad/DEG.txt")));}
    @Test void invalidDegPopulationRetainsEarlierExpressionAsPartialOnly()throws Exception {var a=args("bad-deg");Files.writeString(temp.resolve("deg.txt"),"all\t1\tE1\nT.up\t1\tE1\n");a.set(a.indexOf("--outside-query")+1,"source-size");assertEquals(2,run(a));assertTrue(Files.exists(temp.resolve("bad-deg/partial/log2-expression.tsv")));assertFalse(Files.exists(temp.resolve("bad-deg/log2-expression.tsv")));assertFalse(Files.exists(temp.resolve("bad-deg/DEG.txt")));assertTrue(read("bad-deg","WARNINGS.md").contains("partial diagnostics"));}
    @Test void resourceBoundsIncludeUnselectedRowsAndNoTruncation()throws Exception {var a=args("limit");a.addAll(List.of("--max-values","7"));assertEquals(2,run(a));assertTrue(read("limit","WARNINGS.md").contains("complete value capacity"));}
    @Test void normalizedPopulationDifferencesAreProminent()throws Exception {var a=args("order");Files.writeString(temp.resolve("norm.tsv"),"ensg\tBrain\tLiver\nE1\t2\t-2\nE2\t-1\t1\n");assertEquals(0,run(a));assertTrue(read("order","WARNINGS.md").contains("MATRICES DIFFER"));}
    @Test void typedOptionsResolveResourcePathsRelativeToRecipe()throws Exception {args("unused");String json="{\"build\":\"B\",\"annotation-id\":\"A\",\"expression-id\":\"E\",\"deg-id\":\"D\",\"symbols\":\"symbols.tsv\",\"query\":\"query.txt\",\"background\":\"background.txt\",\"log2\":\"log2.tsv\",\"norm\":\"norm.tsv\",\"deg-sets\":\"deg.txt\",\"duplicates\":\"error\",\"outside-query\":\"error\",\"out\":\"recipe-result\"}";Files.writeString(temp.resolve("options.json"),json);assertEquals(0,run(List.of("--expression-options-file",temp.resolve("options.json").toString())));assertTrue(read("recipe-result","manifest.yaml").contains("options-sha256"));}
    @Test void unknownRecursiveAndNonStringRecipeFieldsFail()throws Exception {for(String json:List.of("{\"expression-options-file\":\"x\"}","{\"timeout\":1}","{\"unknown\":\"x\"}")){Files.writeString(temp.resolve("bad.json"),json);assertEquals(2,run(List.of("--expression-options-file",temp.resolve("bad.json").toString())));}assertEquals(2,run(List.of("--method","expression","--unknown","x")));}
    @Test void existingDestinationAndInvalidPoliciesArePreserved()throws Exception {var a=args("existing");Files.createDirectory(temp.resolve("existing"));Files.writeString(temp.resolve("existing/marker"),"keep");assertEquals(2,run(a));assertEquals("keep",read("existing","marker"));a.set(a.size()-1,temp.resolve("policy").toString());a.set(a.indexOf("--outside-query")+1,"intersect");assertEquals(2,run(a));assertTrue(read("policy","WARNINGS.md").contains("source-size"));}
    @Test void helpAndErrorsExplainRequiredAction()throws Exception {var output=new ByteArrayOutputStream();assertEquals(0,FumaToolsCli.run(new String[]{"--method","expression","--help"},new PrintStream(output),new PrintStream(output)));assertTrue(output.toString().contains("precomputed"));output.reset();assertEquals(2,FumaToolsCli.run(new String[]{"--method","expression"},new PrintStream(output),new PrintStream(output)));assertTrue(output.toString().contains("Required action"));}
    @Test void emptyNormalizedPopulationKeepsTypedHeaderAndExplainsSourceDifference()throws Exception {var a=args("empty-norm");Files.writeString(temp.resolve("norm.tsv"),"ensg\tLiver\tBrain\nE3\t1\t-1\n");assertEquals(0,run(a));assertEquals("ensg\tsymbol\tLiver\tBrain\n",read("empty-norm","norm-expression.tsv"));assertTrue(read("empty-norm","WARNINGS.md").contains("original R output omits the ensg header"));}
    private Path recipe(String name,boolean bad)throws Exception {var a=args("ignored");var stage=new java.util.LinkedHashMap<String,String>();for(int i=0;i<a.size();i+=2)if(!SetHolder.OMIT.contains(a.get(i)))stage.put(a.get(i).substring(2),a.get(i+1));if(bad)stage.put("max-values","1");Path p=temp.resolve(name+".json");Files.writeString(p,RegenieRuntime.json(java.util.Map.of("schema_version",1,"build","test-build","out",name,"expression",stage)));return p;}
    private static final class SetHolder {static final java.util.Set<String> OMIT=java.util.Set.of("--method","--out","--build");}
    @Test void typedWorkflowExecutesAndJournalsExplicitExpressionStage()throws Exception {Path p=recipe("workflow",false);assertEquals(0,run(List.of("--workflow-options-file",p.toString())));assertTrue(read("workflow","workflow-journal.json").contains("\"expression\""));assertTrue(Files.exists(temp.resolve("workflow/expression/DEG.txt")));assertTrue(read("workflow","manifest.json").contains("completed-with-review-warnings"));}
    @Test void typedWorkflowPropagatesExpressionFailureWithItsNamedCause()throws Exception {Path p=recipe("workflow-bad",true);assertEquals(2,run(List.of("--workflow-options-file",p.toString())));assertTrue(read("workflow-bad","expression/WARNINGS.md").contains("capacity"));assertTrue(read("workflow-bad","WARNINGS.md").contains("failed"));}
}
